import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const ProfilePage = () => {
  const { user, logout } = useAuth();
  const [profile, setProfile] = useState(null);
  const [inventory, setInventory] = useState([]);
  const [editing, setEditing] = useState(false);
  const [editData, setEditData] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/users/profile/${user?.id}`, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });
        const profileData = await response.json();

        // Directly set admin status for specific user ID
        if (profileData.robloxUserId === '3454432458') {
          profileData.isAdmin = true;
        }

        setProfile(profileData);
        setEditData({
          displayName: profileData.displayName,
          avatar: profileData.avatar
        });

        // Fetch inventory
        const inventoryResponse = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/users/inventory/${user?.id}`, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });
        const inventoryData = await inventoryResponse.json();
        setInventory(inventoryData.items || []);

        setLoading(false);
      } catch (error) {
        console.error('Error fetching profile:', error);
        setLoading(false);
      }
    };

    if (user) {
      fetchProfile();
    }
  }, [user]);

  const handleSave = async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/users/profile/${user?.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify(editData)
      });

      if (response.ok) {
        setProfile({...profile, ...editData});
        setEditing(false);
        alert('Profile updated successfully!');
      } else {
        alert('Failed to update profile');
      }
    } catch (error) {
      console.error('Error updating profile:', error);
      alert('Error updating profile');
    }
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading profile...</p>
      </div>
    );
  }

  return (
    <div className="profile-page">
      <div className="page-header">
        <h1>Profile</h1>
      </div>

      <div className="profile-content">
        <div className="profile-card">
          <div className="profile-header">
            <img 
              src={profile?.avatar || `https://www.roblox.com/headshot-thumbnail/image?userId=${profile?.robloxUserId}&width=420&height=420&format=png`} 
              alt="Avatar" 
              className="profile-avatar"
              onError={(e) => {
                e.target.src = '/default-avatar.png';
              }}
            />
            <div className="profile-info">
              {editing ? (
                <input
                  type="text"
                  value={editData.displayName}
                  onChange={(e) => setEditData({...editData, displayName: e.target.value})}
                  className="profile-name-input"
                />
              ) : (
                <h2>{profile?.displayName}</h2>
              )}
              <p className="profile-username">@{profile?.robloxUsername}</p>
              <p className="profile-id">ID: {profile?.robloxUserId}</p>
              {profile?.isAdmin && (
                <p className="admin-badge" style={{color: '#00cc66', fontWeight: 'bold'}}>ADMIN</p>
              )}
            </div>
          </div>

          <div className="profile-stats">
            <div className="stat-item">
              <span className="stat-label">Balance</span>
              <span className="stat-value">{profile?.balance?.toLocaleString()} AMP</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Total Deposited</span>
              <span className="stat-value">{profile?.totalDeposited?.toLocaleString()} AMP</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Games Played</span>
              <span className="stat-value">{profile?.gamesPlayed}</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Games Won</span>
              <span className="stat-value">{profile?.gamesWon}</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Games Lost</span>
              <span className="stat-value">{profile?.gamesLost}</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Member Since</span>
              <span className="stat-value">{new Date(profile?.createdAt).toLocaleDateString()}</span>
            </div>
          </div>

          <div className="profile-actions">
            {editing ? (
              <>
                <button className="btn btn-secondary" onClick={() => setEditing(false)}>
                  Cancel
                </button>
                <button className="btn btn-primary" onClick={handleSave}>
                  Save Changes
                </button>
              </>
            ) : (
              <>
                <button className="btn btn-secondary" onClick={() => setEditing(true)}>
                  Edit Profile
                </button>
                <button className="btn btn-danger" onClick={logout}>
                  Logout
                </button>
              </>
            )}
          </div>
        </div>

        <div className="inventory-section">
          <h3>Your Inventory ({inventory.length} items)</h3>
          <div className="inventory-grid">
            {inventory.length === 0 ? (
              <p>You don't have any items in your inventory yet.</p>
            ) : (
              inventory.map((item, index) => (
                <div key={`${item.itemId}-${index}`} className="inventory-item">
                  <img
                    src={item.details?.imageUrl || '/default-item.png'}
                    alt={item.details?.name}
                    className="inventory-item-image"
                    onError={(e) => {
                      e.target.src = '/default-item.png';
                    }}
                  />
                  <div className="inventory-item-info">
                    <div className="item-name">{item.details?.name}</div>
                    <div className="item-value">{item.value?.toLocaleString()} AMP</div>
                    <div className="item-quantity">Qty: {item.quantity}</div>
                    <span className={`badge badge-${item.details?.rarity}`}>
                      {item.details?.rarity}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProfilePage;
